#!/usr/bin/env python3
import os, sys, shutil, subprocess, time, socket, json, re, signal

BASE = "/tmp/explore/drill-render/runs"
EXE = "/workspace/executable"


def free_port(start=8305):
    p = start
    while True:
        s = socket.socket()
        try:
            s.bind(("127.0.0.1", p))
            s.close()
            return p
        except OSError:
            p += 1
        finally:
            try:
                s.close()
            except Exception:
                pass


def run(name, files, extra_args=None, nreveal=1, copy_media=True, urls=None):
    """files: dict path->content (str or bytes). Returns dict."""
    d = os.path.join(BASE, name)
    if os.path.exists(d):
        shutil.rmtree(d)
    os.makedirs(d)
    for p, c in files.items():
        fp = os.path.join(d, p)
        os.makedirs(os.path.dirname(fp), exist_ok=True)
        mode = "wb" if isinstance(c, bytes) else "w"
        with open(fp, mode) as f:
            f.write(c)
    if copy_media:
        for m in ("test.mp3", "thetempest.webp"):
            if not os.path.exists(os.path.join(d, m)):
                shutil.copy(os.path.join("/tmp/explore/_example_master", m), os.path.join(d, m))
    port = free_port()
    args = [EXE, "drill", d, "--port", str(port), "--open-browser", "false"]
    if extra_args:
        args += extra_args
    logpath = os.path.join(BASE, name + ".log")
    logf = open(logpath, "w")
    proc = subprocess.Popen(args, stdout=logf, stderr=subprocess.STDOUT)
    pages = []
    extra = {}
    try:
        ok = False
        for _ in range(200):
            if proc.poll() is not None:
                break
            try:
                s = socket.create_connection(("127.0.0.1", port), 0.2)
                s.close()
                ok = True
                break
            except OSError:
                time.sleep(0.05)
        if not ok:
            logf.close()
            return {"error": "server never started", "log": open(logpath).read(), "port": port, "dir": d,
                    "rc": proc.poll()}

        def get(path="/"):
            return subprocess.run(["curl", "-s", "http://127.0.0.1:%d%s" % (port, path)],
                                  capture_output=True, text=True).stdout

        pages.append(get())
        for _ in range(nreveal):
            subprocess.run(["curl", "-s", "-o", "/dev/null", "-X", "POST",
                            "http://127.0.0.1:%d/" % port, "-d", "action=Reveal"], capture_output=True)
            pages.append(get())
        if urls:
            for u in urls:
                r = subprocess.run(["curl", "-s", "-i", "http://127.0.0.1:%d%s" % (port, u)],
                                   capture_output=True, text=True)
                extra[u] = r.stdout
    finally:
        proc.terminate()
        try:
            proc.wait(timeout=5)
        except Exception:
            proc.kill()
        logf.close()
    out = {"pages": pages, "dir": d, "port": port, "log": open(logpath).read()}
    if extra:
        out["urls"] = extra
    return out


QRE = re.compile(r'<div class="question rich-text">(.*?)</div><div class="answer rich-text">(.*?)</div></div></div></div>', re.S)


def qa(page):
    m = QRE.search(page)
    if not m:
        return (None, None)
    return m.group(1), m.group(2)


def show(name, files, extra_args=None, nreveal=1, urls=None):
    r = run(name, files, extra_args, nreveal, urls=urls)
    if "error" in r:
        print("ERROR:", r["error"], "rc=", r.get("rc"))
        print(r["log"])
        return r
    for i, p in enumerate(r["pages"]):
        q, a = qa(p)
        print("### page %d" % i)
        if q is None:
            print("[no card div] page:")
            print(p[:4000])
        else:
            print("--Q--")
            print(q)
            print("--A--")
            print(a)
    for u, v in (r.get("urls") or {}).items():
        print("### URL", u)
        print(v[:1500])
    if r["log"].strip():
        print("--LOG--")
        print(r["log"])
    return r
